/**
 * The discovery sweep: every business category, across every target city.
 *
 * Two design constraints shaped this, both learned from live failures:
 *
 * 1. Broad multi-category queries get 504'd by every public Overpass instance.
 *    So the sweep is broken into one small query per run, advanced by a cursor
 *    in the _state tab. A failure costs one combination, not the whole run.
 *
 * 2. Roughly 90% of OSM business entries carry no phone and no website, and are
 *    useless to us. Overpass can filter on tag presence server-side, so we ask
 *    only for entries that already have a contact channel. Far smaller payloads
 *    and far less to discard.
 */

const CITIES = [
  { name: 'Lahore', bbox: '31.35,74.15,31.65,74.50' },
  { name: 'Karachi', bbox: '24.75,66.95,25.05,67.25' },
  { name: 'Islamabad', bbox: '33.60,72.95,33.78,73.20' },
  { name: 'Rawalpindi', bbox: '33.52,73.00,33.68,73.15' },
  { name: 'Faisalabad', bbox: '31.36,73.03,31.50,73.18' },
  { name: 'Multan', bbox: '30.10,71.40,30.26,71.55' },
  { name: 'Peshawar', bbox: '33.95,71.40,34.06,71.62' },
  { name: 'Gujranwala', bbox: '32.10,74.10,32.22,74.25' },
  { name: 'Sialkot', bbox: '32.44,74.48,32.56,74.60' },
];

/**
 * Category groups. Together these cover essentially every commercial OSM tag —
 * the eight priority verticals are a scoring input, not a filter, so nothing is
 * excluded for being outside them.
 *
 * `shop` and `office` are the densest tags, so they are split rather than
 * queried wholesale; a single `nwr["shop"]` over Karachi is exactly the kind of
 * query that times out.
 */
const CATEGORY_GROUPS = [
  { key: 'office', selector: '["office"]' },
  { key: 'craft', selector: '["craft"]' },
  { key: 'healthcare', selector: '["healthcare"]' },
  {
    key: 'shop_retail',
    selector: '["shop"~"^(supermarket|convenience|department_store|mall|general|variety_store|wholesale|trade)$"]',
  },
  {
    key: 'shop_goods',
    selector: '["shop"~"^(clothes|shoes|jewelry|furniture|electronics|computer|mobile_phone|hardware|doityourself|paint|florist|books|stationery|sports|toys|optician|cosmetics|chemist)$"]',
  },
  {
    key: 'shop_auto',
    selector: '["shop"~"^(car|car_repair|car_parts|motorcycle|tyres|bicycle|fuel)$"]',
  },
  {
    key: 'shop_services',
    selector: '["shop"~"^(hairdresser|beauty|laundry|dry_cleaning|travel_agency|copyshop|printing|tailor|photo|funeral_directors|estate_agent|insurance)$"]',
  },
  {
    key: 'amenity_food',
    selector: '["amenity"~"^(restaurant|cafe|fast_food|bar|pub|ice_cream|food_court|catering)$"]',
  },
  {
    key: 'amenity_education',
    selector: '["amenity"~"^(school|college|university|language_school|driving_school|music_school|training|childcare|kindergarten|prep_school)$"]',
  },
  {
    key: 'amenity_health',
    selector: '["amenity"~"^(clinic|doctors|dentist|hospital|pharmacy|veterinary|nursing_home)$"]',
  },
  {
    key: 'amenity_finance',
    selector: '["amenity"~"^(bank|bureau_de_change|money_transfer|atm|payment_centre)$"]',
  },
  {
    key: 'amenity_services',
    selector: '["amenity"~"^(car_rental|car_wash|coworking_space|internet_cafe|marketplace|studio|events_venue|conference_centre|cinema|nightclub|gym)$"]',
  },
  {
    key: 'tourism_stay',
    selector: '["tourism"~"^(hotel|guest_house|motel|hostel|apartment|resort)$"]',
  },
  {
    key: 'leisure_fitness',
    selector: '["leisure"~"^(fitness_centre|sports_centre|swimming_pool|golf_course)$"]',
  },
];

/**
 * Ask Overpass only for entries that already carry a contact channel. Four
 * sub-queries because OSM spells contact details several ways and Overpass has
 * no "any of these tags exist" operator.
 */
function buildQuery(bbox, selector, timeout) {
  const t = timeout || 90;
  const contactTags = ['phone', 'contact:phone', 'website', 'contact:website'];
  const parts = contactTags
    .map((tag) => `  nwr${selector}["name"]["${tag}"](${bbox});`)
    .join('\n');
  return `[out:json][timeout:${t}];\n(\n${parts}\n);\nout tags center 500;`;
}

/** Flat list of every city x category combination, in sweep order. */
function combinations() {
  const out = [];
  for (const city of CITIES) {
    for (const group of CATEGORY_GROUPS) {
      out.push({
        city: city.name,
        bbox: city.bbox,
        categoryKey: group.key,
        selector: group.selector,
      });
    }
  }
  return out;
}

/** Pick the combination at `cursor`, wrapping around at the end of the sweep. */
function atCursor(cursor) {
  const all = combinations();
  const n = all.length;
  const i = ((Number(cursor) || 0) % n + n) % n;
  const combo = all[i];
  return {
    index: i,
    total: n,
    nextCursor: (i + 1) % n,
    ...combo,
    query: buildQuery(combo.bbox, combo.selector),
    sourceQuery: `${combo.categoryKey} @ ${combo.city}`,
  };
}



// --- n8n wrapper ---
// Pick up the sweep position from the _state tab. A missing or
// unparseable cursor starts the sweep from the beginning rather than
// failing the run.
let cursor = 0;
try {
  for (const item of $('Read _state').all()) {
    const r = item.json || {};
    if (String(r.key || '').trim() === 'wf1_cursor') {
      const n = parseInt(String(r.value).trim(), 10);
      if (Number.isFinite(n)) cursor = n;
    }
  }
} catch (e) { cursor = 0; }

const t = atCursor(cursor);

return [{ json: {
  city: t.city,
  bbox: t.bbox,
  category_key: t.categoryKey,
  cursor: t.index,
  next_cursor: t.nextCursor,
  total_combinations: t.total,
  overpass_query: t.query,
  source_query: t.sourceQuery,
  run_id: String(Date.now()),
  started_at: new Date().toISOString(),
} }];

/**
 * Normalises a raw Overpass response into raw_candidates-shaped rows.
 *
 * This is the single source of truth for the logic. `scripts/build-code-node.js`
 * wraps it for the n8n Code node, and `scripts/test-normalize.js` exercises it
 * against the captured fixture — so the tested code and the deployed code
 * cannot drift apart.
 *
 * Dependency-free apart from crypto, because n8n Code nodes cannot import
 * project files.
 */
const crypto = require('crypto');

// --- helpers ---------------------------------------------------------------

/** Overpass spreads contact details across several tag spellings. */
function pick(tags, ...keys) {
  for (const k of keys) {
    const v = tags[k];
    if (v && String(v).trim()) return String(v).trim();
  }
  return '';
}

/**
 * Link shorteners and social profiles are not a company's own site. Hashing one
 * as identity would collapse every business behind the same shortener into a
 * single deduplicated lead, silently discarding real prospects.
 */
const NOT_A_HOMEPAGE = new Set([
  'share.google', 'goo.gl', 'g.page', 'maps.app.goo.gl', 'google.com',
  'sites.google.com', 'business.site', 'bit.ly', 'tinyurl.com', 'linktr.ee',
  'facebook.com', 'm.facebook.com', 'fb.me', 'fb.com', 'instagram.com',
  'twitter.com', 'x.com', 'linkedin.com', 'youtube.com', 'youtu.be',
  'wa.me', 'api.whatsapp.com', 'chat.whatsapp.com', 'tiktok.com',
]);

/** Strip protocol, www, port, path and query; lowercase. */
function normalizeDomain(url) {
  if (!url) return '';
  let s = String(url).trim().toLowerCase();
  s = s.replace(/^https?:\/\//, '').replace(/^www\./, '');
  s = s.split('/')[0].split('?')[0].split('#')[0].split(':')[0];
  if (!/^[a-z0-9.-]+\.[a-z]{2,}$/.test(s)) return '';
  return NOT_A_HOMEPAGE.has(s) ? '' : s;
}

/**
 * Pakistani phone numbers to E.164, or '' when the input cannot be trusted.
 * Landlines are 9 digits after the country code, mobiles 10.
 */
function toE164PK(raw) {
  if (!raw) return '';
  let s = String(raw).split(/[;,/]|\bor\b/i)[0]; // tags often hold several numbers
  s = s.replace(/\(0\)/g, '').replace(/[^\d+]/g, '');
  if (!s) return '';

  if (s.startsWith('+92')) s = s;
  else if (s.startsWith('0092')) s = '+92' + s.slice(4);
  else if (s.startsWith('92') && s.length >= 11) s = '+92' + s.slice(2);
  else if (s.startsWith('0')) s = '+92' + s.slice(1);
  else if (/^\d{9,10}$/.test(s)) s = '+92' + s;
  else return '';

  return /^\+92\d{9,10}$/.test(s) ? s : '';
}

/** PK mobiles are +923XXXXXXXXX — the numbers reachable on WhatsApp. */
function isMobilePK(e164) {
  return /^\+923\d{9}$/.test(e164);
}

/** Collapse punctuation and company suffixes so name variants match. */
function normalizeName(name) {
  return String(name || '')
    .toLowerCase()
    .replace(/[^\w\s]/g, ' ')
    .replace(/\b(pvt|private|ltd|limited|co|company|inc|llc|and|the)\b/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function sha1(s) {
  return crypto.createHash('sha1').update(s).digest('hex');
}

function categoryOf(tags) {
  if (tags.office) return 'office:' + tags.office;
  if (tags.shop) return 'shop:' + tags.shop;
  if (tags.healthcare) return 'healthcare:' + tags.healthcare;
  if (tags.amenity) return 'amenity:' + tags.amenity;
  if (tags.craft) return 'craft:' + tags.craft;
  return 'other';
}

function addressOf(tags) {
  return [
    pick(tags, 'addr:housenumber'),
    pick(tags, 'addr:street'),
    pick(tags, 'addr:suburb', 'addr:neighbourhood'),
    pick(tags, 'addr:city'),
  ].filter(Boolean).join(', ');
}

/**
 * Institutions and government facilities are not prospects for an automation
 * agency — they do not buy this way. Filtering them here keeps the sheet
 * honest rather than padding the count.
 */
const INSTITUTIONAL = /\b(combined military|cmh|army|navy|air force|government|govt|district headquarters|dhq|thq|tehsil|punjab government|social security|railway|police|jail|prison|university|college of|medical college|public school)\b/i;

// --- main ------------------------------------------------------------------

/**
 * @param {Array}  elements  Overpass `elements` array
 * @param {Object} opts      { city, sourceQuery, now }
 * @returns {{rows: Array, stats: Object}}
 */
function normalizeOverpass(elements, opts) {
  const city = (opts && opts.city) || '';
  const sourceQuery = (opts && opts.sourceQuery) || 'overpass';
  const now = (opts && opts.now) || new Date().toISOString();

  const stats = {
    received: elements.length,
    unnamed: 0,
    institutional: 0,
    noContact: 0,
    dupInRun: 0,
    web: 0,
    noWeb: 0,
  };

  const rows = [];
  const seen = new Set();

  for (const el of elements) {
    const tags = el.tags || {};
    const name = pick(tags, 'name:en', 'name');
    if (!name) { stats.unnamed++; continue; }

    if (INSTITUTIONAL.test(name)) { stats.institutional++; continue; }

    const rawPhone = pick(tags, 'phone', 'contact:phone', 'contact:mobile', 'mobile');
    const rawSite = pick(tags, 'website', 'contact:website', 'url');

    const phone = toE164PK(rawPhone);
    const domain = normalizeDomain(rawSite);

    // No reachable channel is not a lead.
    if (!phone && !domain) { stats.noContact++; continue; }

    // Domain is the stronger identity; otherwise name + city + phone.
    const lead_id = domain
      ? sha1(domain)
      : sha1([normalizeName(name), city.toLowerCase(), phone].join('|'));

    if (seen.has(lead_id)) { stats.dupInRun++; continue; }
    seen.add(lead_id);

    const hasWebsite = Boolean(domain);
    if (hasWebsite) stats.web++; else stats.noWeb++;

    rows.push({
      candidate_id: lead_id,
      lead_id,
      company_name: name,
      website: domain ? 'https://' + domain : '',
      normalized_domain: domain,
      phone_raw: rawPhone,
      phone_e164: phone,
      whatsapp_ready: phone ? isMobilePK(phone) : false,
      address: addressOf(tags),
      city,
      country: 'Pakistan',
      region: 'PK',
      category: categoryOf(tags),
      source: 'osm_overpass',
      source_query: sourceQuery,
      discovered_at: now,
      status: 'new',
      has_website: hasWebsite,
    });
  }

  return { rows, stats };
}



// --- n8n wrapper ---
const payload = $input.first().json;
const elements = payload.elements || [];
const cfg = $('Config').first().json;

const { rows, stats } = normalizeOverpass(elements, {
  city: cfg.city,
  sourceQuery: cfg.source_query,
});

if (!rows.length) {
  return [{ json: { __empty: true, stats } }];
}
// __empty is set explicitly on every row so the downstream IF tests a
// real boolean rather than relying on undefined coercing to false.
return rows.map(r => ({ json: Object.assign({}, r, { __empty: false, __stats: stats }) }));

// Read both tabs once into a Set. Per-lead lookups would blow through
// the Sheets read quota (~60 req/min) the moment volume grows.
const known = new Set();
for (const nodeName of ['Read Leads', 'Read Leads_NoWeb']) {
  let items = [];
  try { items = $(nodeName).all(); } catch (e) { items = []; }
  for (const it of items) {
    const id = it.json && it.json.lead_id;
    if (id) known.add(String(id).trim());
  }
}

const candidates = $('Normalize').all()
  .map(i => i.json)
  .filter(j => !j.__empty);

const fresh = candidates.filter(c => !known.has(c.lead_id));

return fresh.map(c => ({ json: c }));

// Every mirror refused. Without this the run would end silently and
// look identical to "there were no new leads" — the failure mode that
// lets a dead pipeline go unnoticed for a week.
const cfg = $('Config').first().json;
const err = $input.first().json;

return [{ json: {
  run_id: cfg.run_id,
  workflow: 'wf1-discovery-overpass',
  started_at: cfg.started_at,
  finished_at: new Date().toISOString(),
  candidates_found: '0',
  new_leads: '0',
  errors: '3',
  notes: `ALL OVERPASS MIRRORS FAILED for ${cfg.source_query}. Last error: ` +
    String(err && (err.error || err.message) || 'unknown').slice(0, 300),
} }];

// A mirror answered 200 but the payload held no usable businesses.
// Region-limited mirrors do exactly this, and an unguarded run would
// report success having found nothing.
const cfg = $('Config').first().json;
const stats = ($input.first().json || {}).stats || {};

return [{ json: {
  run_id: cfg.run_id,
  workflow: 'wf1-discovery-overpass',
  started_at: cfg.started_at,
  finished_at: new Date().toISOString(),
  candidates_found: String(stats.received || 0),
  new_leads: '0',
  errors: '1',
  notes: `EMPTY RESPONSE for ${cfg.source_query}. Received ` +
    `${stats.received || 0} elements, none usable. ` +
    `unnamed=${stats.unnamed || 0} noContact=${stats.noContact || 0} ` +
    `institutional=${stats.institutional || 0}. Check whether a mirror ` +
    `is region-limited.`,
} }];
